use crate::types::field::{
    BooleanConstraint, Condition, FieldCondition, FieldType, SchemaField, ValueConstraint,
};
use crate::types::node::{I18nValue, NodeDefine};
use std::collections::HashMap;

pub const NODE_TYPE: &str = "GPT";

#[derive(Default)]
pub struct GptNode;

impl GptNode {
    pub fn new() -> Self {
        Self {}
    }
}

impl NodeDefine for GptNode {
    fn action_type(&self) -> String {
        NODE_TYPE.to_string()
    }

    fn name(&self) -> I18nValue {
        I18nValue {
            zh: "ChatGPT".to_string(),
            en: "ChatGPT".to_string(),
        }
    }

    fn icon(&self) -> String {
        String::from(
            "data:image/svg+xml;base64,",
        )
    }

    fn category(&self) -> Option<I18nValue> {
        Some(I18nValue {
            zh: "AI".to_string(),
            en: "AI".to_string(),
        })
    }

    fn description(&self) -> Option<I18nValue> {
        Some(I18nValue {
            zh: "调用 OpenAI 兼容的聊天模型，返回生成文本与用量。".to_string(),
            en: "Call an OpenAI-compatible chat model and return the generated text and usage."
                .to_string(),
        })
    }

    fn output_schema(&self, _input: HashMap<String, serde_json::Value>) -> Vec<SchemaField> {
        vec![
            SchemaField {
                name: "data".to_string(),
                field_type: FieldType::String,
                item_type: None,
                description: Some(I18nValue {
                    zh: "ChatGPT 节点生成的返回内容".to_string(),
                    en: "Return content generated by ChatGPT nodes".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
            SchemaField {
                name: "prompt_tokens".to_string(),
                field_type: FieldType::Number,
                item_type: None,
                description: Some(I18nValue {
                    zh: "提示词消耗 token 数".to_string(),
                    en: "Prompt tokens used".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
            SchemaField {
                name: "completion_tokens".to_string(),
                field_type: FieldType::Number,
                item_type: None,
                description: Some(I18nValue {
                    zh: "生成部分消耗 token 数".to_string(),
                    en: "Completion tokens used".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
            SchemaField {
                name: "total_tokens".to_string(),
                field_type: FieldType::Number,
                item_type: None,
                description: Some(I18nValue {
                    zh: "总 token 消耗".to_string(),
                    en: "Total tokens used".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
        ]
    }

    fn input_schema(&self) -> Vec<SchemaField> {
        vec![
            SchemaField {
                name: "api_key".to_string(),
                field_type: FieldType::Password,
                item_type: None,
                description: Some(I18nValue {
                    zh: "OpenAI API Key（为空则使用环境变量 OPENAI_API_KEY）".to_string(),
                    en: "OpenAI API key (falls back to OPENAI_API_KEY env var)".to_string(),
                }),
                enums: vec![],
                default: Some("".to_string()),
                condition: None,
            },
            SchemaField {
                name: "base_url".to_string(),
                field_type: FieldType::String,
                item_type: None,
                description: Some(I18nValue {
                    zh: "可选的 API Base URL，兼容自建或代理网关".to_string(),
                    en: "Optional API base URL for self-hosted or proxy gateways".to_string(),
                }),
                enums: vec![],
                default: Some("".to_string()),
                condition: None,
            },
            SchemaField {
                name: "model".to_string(),
                field_type: FieldType::String,
                item_type: None,
                description: Some(I18nValue {
                    zh: "模型名称，如 gpt-4o-mini".to_string(),
                    en: "Model name, e.g. gpt-4o-mini".to_string(),
                }),
                enums: vec![],
                default: Some("gpt-4o-mini".to_string()),
                condition: None,
            },
            SchemaField {
                name: "system_prompt_enabled".to_string(),
                field_type: FieldType::Boolean,
                item_type: None,
                description: Some(I18nValue {
                    zh: "是否设置系统提示词".to_string(),
                    en: "Should system prompts be enabled?".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
            SchemaField {
                name: "system".to_string(),
                field_type: FieldType::String,
                item_type: None,
                description: Some(I18nValue {
                    zh: "系统提示词，可为空".to_string(),
                    en: "Optional system prompt".to_string(),
                }),
                enums: vec![],
                default: Some("".to_string()),
                condition: Some(Condition::Field(FieldCondition {
                    field: "system_prompt_enabled".to_string(),
                    constraint: ValueConstraint::Boolean(BooleanConstraint::from(true)),
                    required: false,
                })),
            },
            SchemaField {
                name: "prompt".to_string(),
                field_type: FieldType::String,
                item_type: None,
                description: Some(I18nValue {
                    zh: "用户提示词".to_string(),
                    en: "User prompt".to_string(),
                }),
                enums: vec![],
                default: None,
                condition: None,
            },
            // TODO: Support response json schema format
            // SchemaField {
            //     name: "response_format_enabled".to_string(),
            //     field_type: FieldType::Boolean,
            //     item_type: None,
            //     description: Some(I18nValue {
            //         zh: "是否自定义Json响应格式".to_string(),
            //         en: "Should the JSON response format be customized?".to_string(),
            //     }),
            //     enums: vec![],
            //     default: None,
            //     condition: None,
            // },
            // SchemaField {
            //     name: "response_json_schema".to_string(),
            //     field_type: FieldType::String,
            //     item_type: None,
            //     description: Some(I18nValue {
            //         zh: "设置JsonSchema，以Json的方式响应".to_string(),
            //         en: "Response JsonSchema Format".to_string(),
            //     }),
            //     enums: vec![],
            //     default: None,
            //     condition: Some(Condition::Field(FieldCondition {
            //         field: "response_format_enabled".to_string(),
            //         constraint: ValueConstraint::Boolean(BooleanConstraint::from(true)),
            //         required: false,
            //     })),
            // }
        ]
    }
}
